function participantResolution(p,id){return p.participantOutcomes?.[id]||null}
function activeParticipant(p,id){return p.members.includes(id)&&!participantResolution(p,id)}
function successfulParticipant(p,id){return activeParticipant(p,id)&&!!p.evaluations[id]?.final&&p.evaluations[id].pass!==false}
function participantResolved(p,id){return !!participantResolution(p,id)||!!p.evaluations[id]?.final}
function participantOutcomeLabel(p,id){return participantResolution(p,id)?.outcome||(p.evaluations[id]?.final?(p.evaluations[id].pass===false?'EVALUATED_BELOW_THRESHOLD':'SUCCESSFULLY_COMPLETED'):'ACTIVE')}
function outcomesOpen(p){return ['APPROVED','STARTED','IN_PROGRESS','EXECUTION_COMPLETED','REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state)}
function refreshIndividualStage(p){if(p.state==='REFLECTION_PENDING'&&p.members.every(id=>participantResolution(p,id)||p.reflections[id]))p.state='EVALUATION_PENDING'}
function participantOutcomesPanel(p){return `<h2>Individual completion outcomes</h2><div class="notice">Every participant is resolved separately. The assigned mentor may propose partial completion, withdrawal or exemption; students may request their own withdrawal. Department Head approval is required. These outcomes preserve historical work and do not confer successful completion or certificate eligibility. Changes after project verification require a future authorized amendment process.</div>${p.members.map(id=>{let resolved=participantResolution(p,id),pending=(p.outcomeRequests||[]).find(r=>r.student===id&&r.state==='PENDING'),privateView=uid===id||mentor(p)||['d1','a1'].includes(uid);return `<div class="card" style="margin:15px 0"><h3>${esc(name(id))}</h3>${pill(participantOutcomeLabel(p,id))}${resolved&&privateView?`<p>${esc(resolved.reason)}</p><p class="meta">Authorized by ${esc(name(resolved.approvedBy))} · ${esc(eventTime(resolved.approvedAt))}</p>`:''}${!resolved&&outcomesOpen(p)&&!pending&&(mentor(p)||uid===id)?btn(uid===id?'Request withdrawal':'Propose completion outcome',`participantOutcomeForm('${id}')`):''}${pending?`<p class="meta">Outcome review pending</p>${privateView?`<p>${esc(pending.outcome)} · ${esc(pending.reason)}</p>${pending.newLead?`<p>Proposed successor lead: ${esc(name(pending.newLead))}</p>`:''}${uid==='d1'&&uid!==pending.requestedBy&&uid!==id?btn('Review outcome',`participantOutcomeReviewForm('${pending.id}')`):''}`:''}`:''}${privateView?`<details><summary>Request history</summary>${(p.outcomeRequests||[]).filter(r=>r.student===id).map(r=>`<p>${esc(r.outcome)} · ${esc(r.state)} · ${esc(name(r.requestedBy))} · ${esc(eventTime(r.requestedAt))}</p><p>${esc(r.reason)}</p>${r.decisionReason?`<p>Decision: ${esc(r.decisionReason)} · ${esc(name(r.decidedBy))} · ${esc(eventTime(r.decidedAt))}</p>`:''}`).join('')||'<p>No requests.</p>'}</details>`:''}</div>`}).join('')}${externalParticipantPanel(p)}`}
function participantOutcomeForm(student){let p=current();if(!activeParticipant(p,student)||!outcomesOpen(p)||!(mentor(p)||uid===student))return;modal(`<h2>${uid===student?'Request withdrawal':'Propose individual outcome'}</h2><form onsubmit="requestParticipantOutcome(event,'${student}')"><label>Outcome<select name="outcome">${(mentor(p)?['PARTIALLY_COMPLETED','WITHDRAWN','EXEMPTED']:['WITHDRAWN']).map(v=>`<option>${v}</option>`).join('')}</select></label><label>Reason and supporting record references<textarea name="reason" required></textarea></label>${student===p.owner?`<label>Successor project lead<select name="newLead"><option value="">Select an active participant</option>${p.members.filter(id=>id!==student&&activeParticipant(p,id)).map(id=>`<option value="${id}">${esc(name(id))}</option>`).join('')}</select></label><p>The successor must acknowledge the proposed lead transfer before the outcome can be approved.</p>`:''}<button class="primary">Submit for independent approval</button></form>`)}
function requestParticipantOutcome(e,student){e.preventDefault();let p=current(),f=new FormData(e.target),outcome=f.get('outcome'),reason=f.get('reason').trim(),newLead=f.get('newLead')||null;if(!outcomesOpen(p)||!activeParticipant(p,student)||!(mentor(p)&&uid!==student||uid===student&&outcome==='WITHDRAWN')||!['PARTIALLY_COMPLETED','WITHDRAWN','EXEMPTED'].includes(outcome)||!reason)return toast('Authorized requester, active participant and reason required.');if((p.outcomeRequests||[]).some(r=>r.student===student&&r.state==='PENDING'))return toast('A request is already pending.');if(p.certs[student])return toast('Resolve the existing certificate through an authorized amendment first.');if(student===p.owner&&(!newLead||newLead===student||!activeParticipant(p,newLead)))return toast('Select an active successor project lead.');if(student!==p.owner)newLead=null;p.outcomeRequests??=[];p.outcomeRequests.push({id:'OR'+Date.now()+'-'+p.outcomeRequests.length,student,outcome,reason,newLead,sourceLead:p.owner,state:'PENDING',requestedBy:uid,requestedAt:new Date().toISOString()});log(p,'Individual outcome review requested for '+name(student));closeModal();render()}
function acknowledgeOutcomeLead(id){let p=current(),r=(p.outcomeRequests||[]).find(r=>r.id===id);if(!r||r.state!=='PENDING'||r.newLead!==uid||!activeParticipant(p,uid)||!outcomesOpen(p))return;r.leadAcknowledgedBy=uid;r.leadAcknowledgedAt=new Date().toISOString();log(p,'Proposed successor acknowledged project lead responsibility');render()}
function participantOutcomeReviewForm(id){let p=current(),r=(p.outcomeRequests||[]).find(r=>r.id===id);if(!r)return;modal(`<h2>Review individual outcome</h2><p>${esc(name(r.student))} · ${esc(r.outcome)}</p><p>${esc(r.reason)}</p>${r.newLead?`<p>Successor: ${esc(name(r.newLead))} · ${r.leadAcknowledgedBy?'Acknowledged':'Awaiting successor acknowledgment'}</p>`:''}<p>Approval preserves existing records, stops new student work in this activity, and excludes this outcome from successful-completion counts and certificates. Unfinished tasks must be reassigned before approval.</p><form onsubmit="decideParticipantOutcome(event,'${id}')"><label>Decision<select name="decision"><option>APPROVED</option><option>REJECTED</option></select></label><label>Decision reason<textarea name="reason" required></textarea></label><button class="primary">Record decision</button></form>`)}
function decideParticipantOutcome(e,id){e.preventDefault();let p=current(),r=(p.outcomeRequests||[]).find(r=>r.id===id),f=new FormData(e.target),decision=f.get('decision'),reason=f.get('reason').trim();if(!r||uid!=='d1'||uid===r.requestedBy||uid===r.student||r.state!=='PENDING'||!outcomesOpen(p)||!activeParticipant(p,r.student)||!reason||!['APPROVED','REJECTED'].includes(decision))return toast('Independent reviewer and current pending request required.');if(decision==='APPROVED'){if(p.certs[r.student]||p.owner!==r.sourceLead)return toast('Certificate or project lead changed. Reject this stale request and resubmit.');if(p.tasks.some(t=>t.assignee===r.student&&!t.done))return toast('Reassign unfinished tasks before approving this outcome.');if(r.student===p.owner&&(!activeParticipant(p,r.newLead)||r.leadAcknowledgedBy!==r.newLead||(p.outcomeRequests||[]).some(x=>x.student===r.newLead&&x.state==='PENDING')))return toast('An active successor must acknowledge the role and have no pending outcome request.');p.participantOutcomes??={};p.participantOutcomes[r.student]={outcome:r.outcome,requestId:r.id,reason:r.reason,approvedBy:uid,approvedAt:new Date().toISOString()};if(r.student===p.owner){p.leadHistory??=[];p.leadHistory.push({from:p.owner,to:r.newLead,reason:'Authorized participant outcome',requestId:r.id,by:uid,time:new Date().toISOString()});p.owner=r.newLead}refreshIndividualStage(p)}r.state=decision;r.decisionReason=reason;r.decidedBy=uid;r.decidedAt=new Date().toISOString();log(p,'Individual outcome request '+decision+' for '+name(r.student));closeModal();render()}
function reassignParticipantTask(e,index){e.preventDefault();let p=current(),task=p.tasks[index],assignee=new FormData(e.target).get('assignee');if(!task||task.done||task.mappingVersion&&['SUBMITTED','VERIFIED'].includes(task.workState)||!(mentor(p)||owner(p))||!['APPROVED','STARTED','IN_PROGRESS','EXECUTION_COMPLETED','REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state)||!activeParticipant(p,assignee))return toast('Choose an active participant for an unfinished task.');task.assignmentHistory??=[];task.assignmentHistory.push({from:task.assignee,to:assignee,by:uid,time:new Date().toISOString()});task.assignee=assignee;log(p,'Unfinished task reassigned: '+task.title);closeModal();render()}
function reassignParticipantTaskForm(index){let p=current();modal(`<h2>Reassign unfinished task</h2><form onsubmit="reassignParticipantTask(event,${index})"><label>Assignee<select name="assignee">${p.members.filter(id=>activeParticipant(p,id)).map(id=>`<option value="${id}">${esc(name(id))}</option>`).join('')}</select></label><button class="primary">Reassign task</button></form>`)}
function outcomeLeadActions(p){return (p.outcomeRequests||[]).filter(r=>r.state==='PENDING'&&r.newLead===uid&&!r.leadAcknowledgedBy).map(r=>`<div class="notice">Proposed project lead transfer from ${esc(name(r.student))}. Historical obligations remain with the project. ${btn('Accept lead responsibility',`acknowledgeOutcomeLead('${r.id}')`)}</div>`).join('')}

function outcomeActionCards(){let rows=visible().flatMap(p=>(p.outcomeRequests||[]).filter(r=>r.state==='PENDING'&&(uid==='d1'||r.newLead===uid&&!r.leadAcknowledgedBy)).map(r=>({p,r})));return rows.length?`<div class="panel" style="margin-top:20px"><h2>Individual outcome reviews & lead transfers</h2>${rows.map(({p,r})=>`<div class="row"><span>${esc(p.title)} · ${esc(name(r.student))} · Pending outcome review</span>${btn('Open participants',`openProject('${p.id}');tab='Participants';render()`)}</div>`).join('')}</div>`:''}
